var doc = Document;
// Goal: a DWG of a floor plan, exported into the connector's exports directory and published.

// 1. The view to export, made or found INSIDE a block. Anything that writes belongs in a block;
//    the export itself does not.
var viewId = Connector.WithTransaction(doc, () => {
  var level = Autodesk.Revit.DB.Level.Create(doc, 0.5);
  Autodesk.Revit.DB.ElementId vftId = null;
  foreach (Autodesk.Revit.DB.ViewFamilyType vft in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.ViewFamilyType))) {
    if (vft.ViewFamily == Autodesk.Revit.DB.ViewFamily.FloorPlan) { vftId = vft.Id; break; }
  }
  var plan = Autodesk.Revit.DB.ViewPlan.Create(doc, vftId, level.Id);
  plan.Name = "Export plan " + System.Guid.NewGuid().ToString("N").Substring(0, 6);
  doc.Regenerate();
  return plan.Id;
});

// 2. Export BETWEEN blocks, at top level. Document.Export manages its own transaction and needs
//    the document not modifiable; inside Connector.WithTransaction it fails with
//    script-target-must-not-be-modifiable. DWGExportOptions defaults are the "AutoCAD 2018"
//    style export; set FileVersion, LayerMapping etc. on it when the consultant specifies them.
var options = new Autodesk.Revit.DB.DWGExportOptions();
var views = new System.Collections.Generic.List<Autodesk.Revit.DB.ElementId> { viewId };
var exportName = "plan-" + System.Guid.NewGuid().ToString("N").Substring(0, 8);
var folder = Connector.ExportsDirectory;
var exported = doc.Export(folder, exportName, views, options);

// 3. Revit names the file <name>.dwg (one view) or <name>-<view name>.dwg (several); check what
//    landed rather than assuming.
var dwgPath = System.IO.Path.Combine(folder, exportName + ".dwg");
var exists = System.IO.File.Exists(dwgPath);
long size = exists ? new System.IO.FileInfo(dwgPath).Length : 0;

// 4. Publish so the file appears in the run's files[] for the user to fetch (files-publish-and-audit-trail).
if (exists) { Connector.Publish(dwgPath); }

// 5. Verify: Export returned true and the file exists with non-zero size.
return new { exported, dwgName = exportName + ".dwg", dwgExists = exists, dwgBytes = size, viewId = viewId.Value };
